import React from 'react';
import './News&Notice.css'; // Corrected: Must match the CSS filename

const ContentListView = ({ title, type }) => {
    const items = [
        { id: 1, title: `${type}: Annual Progress Report 2025/26`, date: "2026-04-01", fileUrl: "#" },
        { id: 2, title: `${type}: Upcoming Branch Selection Notice`, date: "2026-03-15", fileUrl: "#" },
    ];

    return (
        <div className="content-view-container">
            <div className="content-header">
                <h2>{title}</h2>
                <div className="upload-section" style={{margin: '20px 0', padding: '15px', background: '#f0f7f4', borderRadius: '5px', border: '1px dashed #00a86b'}}>
                    <label style={{color: '#00a86b', fontWeight: 'bold'}}>
                        Upload New {type}: 
                        <input type="file" style={{marginLeft: '10px'}} onChange={(e) => alert('File selected: ' + e.target.files[0].name)} />
                    </label>
                </div>
            </div>

            <div className="item-list">
                {items.map(item => (
                    <div key={item.id} className="content-item">
                        <div className="item-info">
                            <span className="item-date">{item.date}</span>
                            <h3>{item.title}</h3>
                        </div>
                        <div className="item-actions">
                            <a href={item.fileUrl} target="_blank" rel="noreferrer" className="action-btn view">View</a>
                            <a href={item.fileUrl} download className="action-btn download">Download</a>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default ContentListView;
